--- HANDOFF.md
@@ -203,10 +203,11 @@ capture асинхронно) во всех путях reconnect.
 - [x] **A3** — Надёжная переустановка блокировки: `PassiveRdpInputBlocker.Rebind` (release+
   refresh сабклассов) + в reconnect-финализаторе форс VO и `Rebind` каждый тик (покрывает
   позднее пересоздание окон mstscax).
-- [ ] **A4** — Политика ViewOnly по чек-листу: **вход в fullscreen не меняет VO** (первый
-  коннект=выкл=работа; VO в fullscreen вручную); **выход**=VO принудительно ВКЛ + scroll;
-  **reconnect**=VO ВКЛ; **переключение вкладок** (клик/Ctrl+Tab)=довести scroll + VO ВКЛ.
-  Правки: `ApplyFullscreenViewOnlyPolicy`, `MarkRdpFullscreenActive`, `NotifyPassiveTabActivated`.
+- [x] **A4** — Политика ViewOnly по чек-листу. `MarkRdpFullscreenActive`: сброс VO-флагов
+  перенесён со входа на выход (вход НЕ меняет VO). `ApplyFullscreenViewOnlyPolicy`: убран
+  форс VO в fullscreen. `NotifyPassiveTabActivated`: форс VO при активации оконной вкладки.
+  `EnableViewOnlyAfterSuccessfulPassiveLayout`: guard против VO в fullscreen (гонка 1-го коннекта).
+  Выход форсит VO (существующий «fullscreen leave input shield» + scroll).
 - [ ] **A5** — Унификация всех путей reconnect: release-capture финализатор + VO policy +
   **переустановка performance-настроек (pFlags)**. Покрыть ActiveX auto-reconnect (по
   таймауту НЕ применяет настройки!), tmrReconnect, RDP8 resize, меню Reconnect/Reconnect All.
@@ -270,3 +271,5 @@ _Журнал изменений HANDOFF:_
   `FinalizeRdpFullscreenExitOnce` отрефакторен на общий `ReleaseRdpInputCaptureOnce`._
 - _A3 — добавлен `InputBlocker.Rebind` (полный re-subclass); reconnect-финализатор форсит
   VO + Rebind на пересозданные окна mstscax._
+- _A4 — политика VO по чек-листу: вход в fullscreen сохраняет VO (не форсит), выход форсит VO,
+  активация вкладки форсит VO, scroll не включает VO в fullscreen (устранена гонка)._
--- mRemoteNG/Connection/Protocol/RDP/RdpProtocol6.cs
@@ -363,8 +363,10 @@ public void NotifyPassiveTabActivated()
                 if (fullscreen)
                     return;

-                if (!ViewOnly)
-                    return;
+                // Переключение на оконную пассивную RDP-вкладку → ViewOnly ВКЛ (защита
+                // пассивного мониторинга) независимо от прежнего состояния.
+                if (!_viewOnly)
+                    SetViewOnly(true, "NotifyPassiveTabActivated");

                 if (!keepScrollable)
                     return;
@@ -493,8 +495,8 @@ private void MarkRdpFullscreenActive(bool active, string source)
             if (active)
             {
                 _fullscreenExitRequestedByMRemote = false;
-                _userManuallyDisabledViewOnly = false;
-                _autoEnableViewOnlyAfterSuccessfulScroll = true;
+                // Вход в fullscreen НЕ меняет ViewOnly — сохраняем текущее состояние
+                // (смотрел в окне с VO → в fullscreen тоже VO; первый коннект VO выкл → работа).
             }
             else
             {
@@ -503,6 +505,10 @@ private void MarkRdpFullscreenActive(bool active, string source)
                     TryReadRdpClientFullscreen(out var rdpFullscreen) && rdpFullscreen;
                 if (wasFullscreen)
                     _fullscreenLeftAtUtc = DateTime.UtcNow;
+                // Выход из fullscreen всегда возвращает пассивный режим: сбрасываем ручное
+                // отключение и разрешаем авто-VO, чтобы scroll-после-выхода форсил ViewOnly.
+                _userManuallyDisabledViewOnly = false;
+                _autoEnableViewOnlyAfterSuccessfulScroll = true;
             }

             LogFullscreenState(source, active);
@@ -802,12 +808,9 @@ protected void ApplyFullscreenViewOnlyPolicy(string source)
                 return;
             }

-            if (IsFullscreenEffective())
-            {
-                if (!_userManuallyDisabledViewOnly)
-                    SetViewOnly(true, source);
-            }
-
+            // По итоговой модели вход в fullscreen НЕ форсит ViewOnly: в fullscreen VO
+            // управляется вручную (первый коннект — работа). ViewOnly включается принудительно
+            // при выходе из fullscreen (scroll), при reconnect и при активации вкладки.
             LogFullscreenState(source, null);
         }

@@ -1664,12 +1667,16 @@ private bool IsCurrentPassiveScrollAtLowerRight(ScrollableControl scrollable, ou

         private void EnableViewOnlyAfterSuccessfulPassiveLayout(string source, bool scrollNeeded)
         {
-            if (_userManuallyDisabledViewOnly || !_autoEnableViewOnlyAfterSuccessfulScroll)
+            // Не включаем VO через scroll, если сессия в fullscreen или входит в него:
+            // в fullscreen VO управляется вручную (устраняет гонку «иногда VO при первом коннекте»).
+            if (_userManuallyDisabledViewOnly || !_autoEnableViewOnlyAfterSuccessfulScroll
+                || _fullscreenRequestedByMRemote || IsFullscreenEffective())
             {
                 Runtime.MessageCollector.AddMessage(MessageClass.DebugMsg,
                     $"RDP passive scroll completed from {source} for host '{connectionInfo?.Hostname}' without auto ViewOnly: " +
                     $"userManuallyDisabledViewOnly={_userManuallyDisabledViewOnly}, " +
-                    $"autoEnableViewOnlyAfterSuccessfulScroll={_autoEnableViewOnlyAfterSuccessfulScroll}");
+                    $"autoEnableViewOnlyAfterSuccessfulScroll={_autoEnableViewOnlyAfterSuccessfulScroll}, " +
+                    $"fullscreenRequested={_fullscreenRequestedByMRemote}, fullscreenEffective={IsFullscreenEffective()}");
                 return;
             }
